scope":"todas","displayOrder":219},{"name":"Whisky Buchanan's","categorySlug":"licores-y-cocktails","price":178,"description":null,"isPopular":false,"noDomicilio":true,"scope":"todas","displayOrder":220},{"name":"Whisky Chivas Regal","categorySlug":"licores-y-cocktails","price":156,"description":null,"isPopular":false,"noDomicilio":true,"scope":"todas","displayOrder":221},{"name":"Whisky J.W. Etiqueta Negra","categorySlug":"licores-y-cocktails","price":190,"description":null,"isPopular":false,"noDomicilio":true,"scope":"todas","displayOrder":222},{"name":"Caribe Cooler","categorySlug":"licores-y-cocktails","price":110,"description":null,"isPopular":false,"noDomicilio":true,"scope":"todas","displayOrder":223},{"name":"Conga","categorySlug":"licores-y-cocktails","price":114,"description":null,"isPopular":false,"noDomicilio":true,"scope":"todas","displayOrder":224},{"name":"Conga sin Alcohol","categorySlug":"licores-y-cocktails","price":105,"description":null,"isPopular":false,"noDomicilio":false,"scope":"todas","displayOrder":225},{"name":"Daiquiri","categorySlug":"licores-y-cocktails","price":109,"description":null,"isPopular":false,"noDomicilio":true,"scope":"todas","displayOrder":226},{"name":"Daiquiri sin Alcohol","categorySlug":"licores-y-cocktails","price":96,"description":null,"isPopular":false,"noDomicilio":false,"scope":"todas","displayOrder":227},{"name":"Limonada Eléctrica","categorySlug":"licores-y-cocktails","price":109,"description":null,"isPopular":false,"noDomicilio":true,"scope":"todas","displayOrder":228},{"name":"Margarita","categorySlug":"licores-y-cocktails","price":109,"description":null,"isPopular":false,"noDomicilio":true,"scope":"todas","displayOrder":229},{"name":"Margarita sin Alcohol","categorySlug":"licores-y-cocktails","price":100,"description":null,"isPopular":false,"noDomicilio":false,"scope":"todas","displayOrder":230},{"name":"Piñada","categorySlug":"licores-y-cocktails","price":100,"description":null,"isPopular":false,"noDomicilio":t