\echo '=== V1. El volumen inserta exactamente 147 pedidos del motor real en la organizacion demo ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select count(*)::int as pedidos_deberia_ser_147 from restaurantes.orders where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo');
rollback;

\echo '=== V2. IDEMPOTENCIA: aplicar el MISMO volumen dos veces deja los mismos pedidos (sin duplicar) ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select public.seed_volumen();
select count(*)::int as pedidos_tras_dos_corridas_deberia_ser_147 from restaurantes.orders where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo');
rollback;

\echo '=== V2b. IDEMPOTENCIA: clientes, conversaciones, handoffs y contactos tampoco se duplican ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select public.seed_volumen();
select (
  (select count(*) from restaurantes.customers where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 37
  and (select count(*) from restaurantes.whatsapp_conversations where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 31
  and (select count(*) from restaurantes.conversation_handoff where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 3
  and (select count(*) from restaurantes.callback_requests where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 3
)::int as sin_duplicados_deberia_ser_1;
rollback;

\echo '=== V3. COHERENCIA: el total de cada pedido es la suma de sus renglones menos el descuento del motor (0 pedidos incoherentes) ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select count(*)::int as pedidos_con_total_incoherente_deberia_ser_0 from restaurantes.orders o where o.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and abs(o.total - ((select coalesce(sum((i->>'price')::numeric * (i->>'quantity')::numeric), 0) from jsonb_array_elements(o.items) i) - coalesce((regexp_match(o.notes, 'Promoción aplicada: [A-Z0-9_-]+ \(-\$([0-9.]+)\)'))[1]::numeric, 0))) > 0.005;
rollback;

\echo '=== V4. Los renglones son del menu sembrado: mismo nombre y mismo precio que el producto de la organizacion (0 discrepancias) ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select count(*)::int as renglones_fuera_del_menu_deberia_ser_0
  from restaurantes.orders o cross join lateral jsonb_array_elements(o.items) i
 where o.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')
   and not exists (select 1 from restaurantes.products p where p.organization_id = o.organization_id and p.name = i->>'name' and p.price = (i->>'price')::numeric);
rollback;

\echo '=== V5. Las 5 sucursales activas reciben pedidos y T4 (inactiva, sin menu) ninguno ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select (
  (select count(distinct bd.slug) from restaurantes.orders o join restaurantes.branch_detail bd on bd.property_id = o.property_id where o.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 5
  and (select count(*) from restaurantes.orders o join restaurantes.branch_detail bd on bd.property_id = o.property_id where o.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and bd.slug = 't4-pendiente') = 0
)::int as cinco_sucursales_y_t4_vacia_deberia_ser_1;
rollback;

\echo '=== V6. Reglas duras: ningun pedido a domicilio bajo $200 (antes de descuentos) ni con alcohol (no_domicilio) ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select (
  (select count(*) from restaurantes.orders o where o.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and o.canal = 'domicilio' and (select coalesce(sum((i->>'price')::numeric * (i->>'quantity')::numeric), 0) from jsonb_array_elements(o.items) i) < 200)
  + (select count(*) from restaurantes.orders o cross join lateral jsonb_array_elements(o.items) i join restaurantes.products p on p.organization_id = o.organization_id and p.name = i->>'name'
      where o.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and o.canal = 'domicilio' and p.no_domicilio)
)::int as violaciones_de_reglas_duras_deberia_ser_0;
rollback;

\echo '=== V6b. Propina solo con tarjeta; promociones solo al recoger ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select (
  (select count(*) from restaurantes.orders o where o.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and o.propina is not null and o.payment_method <> 'tarjeta')
  + (select count(*) from restaurantes.orders o where o.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and o.canal = 'domicilio' and coalesce((regexp_match(o.notes, 'Promoción aplicada: [A-Z0-9_-]+ \(-\$([0-9.]+)\)'))[1]::numeric, 0) > 0)
)::int as propina_o_promo_indebida_deberia_ser_0;
rollback;

\echo '=== V7. El contador de pedidos de cada cliente coincide con sus pedidos reales (sin cancelados) ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select count(*)::int as clientes_con_contador_incoherente_deberia_ser_0
  from restaurantes.customers cu
 where cu.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')
   and cu.order_count <> (select count(*) from restaurantes.orders o where o.customer_id = cu.id and o.status <> 'cancelado');
rollback;

\echo '=== V8. Todo lo escrito esta en el rango ficticio reservado 0001xxxxxx (0 telefonos fuera de rango) ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select (
  (select count(*) from restaurantes.orders where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and customer_phone !~ '^0001[0-9]{6}$')
  + (select count(*) from restaurantes.customers where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and phone !~ '^0001[0-9]{6}$')
  + (select count(*) from restaurantes.whatsapp_conversations where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and right(phone, 10) !~ '^0001[0-9]{6}$')
)::int as telefonos_fuera_de_rango_deberia_ser_0;
rollback;

\echo '=== V9. Handoffs: 3 tomas (3 pendientes recientes, el resto cerradas) ligadas a una conversacion; ninguna toma abierta duplicada ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select (
  (select count(*) from restaurantes.conversation_handoff where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 3
  and (select count(*) from restaurantes.conversation_handoff where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and estado = 'pendiente') = 3
  and not exists (select 1 from restaurantes.conversation_handoff h where h.organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and not exists (select 1 from restaurantes.whatsapp_conversations c where c.id = h.conversation_id))
)::int as handoffs_coherentes_deberia_ser_1;
rollback;

\echo '=== V10. Cada conversacion completada esta ligada a un pedido real ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select count(*)::int as conversaciones_completadas_sin_pedido_deberia_ser_0 from restaurantes.whatsapp_conversations where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and status = 'completed' and order_id is null;
rollback;

\echo '=== V10b. Contactos: 3 registrados, 3 sin resolver (estado 'nuevo') ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
select (
  (select count(*) from restaurantes.callback_requests where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo')) = 3
  and (select count(*) from restaurantes.callback_requests where organization_id = (select id from core.organization where slug = 'los-taquitos-de-pm-demo') and not resolved and status = 'nuevo') = 3
)::int as contactos_coherentes_deberia_ser_1;
rollback;

\echo '=== V11. RECHAZADO (debe fallar): una organizacion que NO esta marcada como demo no recibe volumen ==='
begin;
select public.seed_volumen_no_demo() as should_fail;
rollback;

