rollback;

\echo '=== V14. CROSS-TENANT: el staff de otra organizacion no lee ningun pedido de la demo (RLS: 0 filas) ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
set local role authenticated;
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-0000000f0014', true);
select count(*)::int as pedidos_de_la_demo_visibles_para_otro_staff_deberia_ser_0 from restaurantes.orders where organization_id <> '00000000-0000-0000-0000-0000000f0002';
rollback;

\echo '=== V15. RECHAZADO (debe fallar): anon no lee los pedidos sembrados ==='
begin;
select public.seed_pm_demo_marcado();
select public.seed_volumen();
set local role anon;
